import { test, expect } from '@playwright/test';

test.describe('Confirmation Modal for Deleting a Record', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com'); // Replace with the actual URL
  });

  test('should display confirmation modal when delete button is clicked', async ({ page }) => {
    await page.getByRole('button', { name: /delete/i }).click();
    const modal = page.getByRole('dialog', { name: /confirm deletion/i });
    await expect(modal).toBeVisible();
  });

  test('should not delete the record if confirmation is not given', async ({ page }) => {
    await page.getByRole('button', { name: /delete/i }).click();
    await page.getByRole('button', { name: /cancel/i }).click();
    const record = page.getByText(/record name/i); // Replace with actual record name
    await expect(record).toBeVisible();
  });

  test('should delete the record if confirmation is given', async ({ page }) => {
    await page.getByRole('button', { name: /delete/i }).click();
    await page.getByRole('button', { name: /confirm/i }).click();
    const record = page.getByText(/record name/i); // Replace with actual record name
    await expect(record).not.toBeVisible();
  });
});
